#!/usr/bin/env python3
"""Build a hash-bound conclusion from completed strict native comparisons."""
import hashlib,json,struct
from pathlib import Path
A=Path(__file__).resolve().parent.parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
evidence={}
def read(p):
 p=p.resolve();evidence[str(p)]=sha(p);return json.loads(p.read_text())
revisions=[]
for label,candidate,control,profile in [
 ('F20 JOB1','candidate-v2-witness','control-v1-witness','native-v1.json'),
 ('F21 JOB2','candidate-appv2','control-appv2','native-appv2.json'),
 ('F22 JOB3','candidate-appv3','control-appv3','native-appv3.json')]:
 c=read(A/'validation'/candidate/'check-independent-v1.json')
 b=read(A/'validation'/control/'check-independent-v1.json')
 assert c['status']=='PASS_AJ01_SAME_ELF_FULL_NATIVE_FUNCTIONAL_AND_ORDERED_SEMANTICS'
 assert b['status']=='PASS_SAME_ELF_CAPABILITY_OFF_NATIVE_ORACLE'
 p=read(A/'analysis'/profile)
 cc=c['health']['cycles'];bc=b['health']['cycles']
 assert cc==p['candidate']['cycles'] and bc==p['control']['cycles']
 run=A/'validation'/candidate/'run';stats=run/'async-stats.bin';evidence[str(stats.resolve())]=sha(stats)
 hints=run/'async-hint-stats.bin';hint=None
 if hints.exists():evidence[str(hints.resolve())]=sha(hints);hint=list(struct.unpack('<4I',hints.read_bytes()))
 revisions.append(dict(label=label,control_cycles=bc,candidate_cycles=cc,total_change_percent=(sum(cc)/sum(bc)-1)*100,warm_change_percent=(cc[1]/bc[1]-1)*100,qualified_prior_cycles=[3980965,4366717],different_ELF_prior_total_change_percent=(sum(cc)/8347682-1)*100,async_stats=list(struct.unpack('<16I',stats.read_bytes())),hint_stats=hint,strict_candidate=str((A/'validation'/candidate/'check-independent-v1.json').resolve()),strict_control=str((A/'validation'/control/'check-independent-v1.json').resolve())))
for p in ['work-core/rtl-ready-v2.json','validation/front-v2/result.json','repair/qualification-v1.json','validation/passive-witness-equivalence-v1.json','validation/lifetime-negative-v1/result.json','work-app-v2/evidence/repair-fastpath-v1/result.json','work-app-v3/evidence/hint-tests-v1/result.json','../mesh-integrated-v1/analysis/adaptive-v4-conclusion.json']:
 read(A/p)
result=dict(schema=1,decision='RETAIN_QUALIFIED_BASELINE_NO_PHYSICAL_FIT_OR_DEPLOYMENT',scope='AJ01 asynchronous raw/triangle jobs in os30/SM64; two prepared full native render/game/audio intervals per app revision.',revisions=revisions,observations={'v3_warm_queued_jobs':76,'v3_warm_cpu_repairs':0,'v3_warm_total_cycles':5105025,'v3_warm_lease_pending_cycles':599773,'v3_warm_lease_pending_with_GPU_fragment_cycles':524552,'v3_warm_output_full_cycles':580588,'v3_warm_output_full_with_GPU_fragment_cycles':539898,'v3_warm_raw_transform_cycles':202210,'v3_warm_GPU_fragment_cycles':1439517,'counts_are_overlapping_not_additive':True},conclusion='The asynchronous stream works correctly and overlaps CPU work, but it does not reduce frame time. Repeated clipping repair is not the remaining primary explanation: v3 has zero warm repairs and still takes 10.19% more cycles than its same-ELF control. Shared raw ownership plus ordered output backpressure serializes later legacy LOADs behind queued raster work. A larger PSRAM bandwidth claim cannot be inferred from these counters.',next_hypothesis='Decouple the legacy raw lease from draining all earlier GPU packets. Priority at safe raw-engine boundaries would require immutable/restored contexts and a tested release/materialization path before ingress-full waits. This is a proposed structural change, not implemented or credited as a speedup.',physical='Prepared source integration only. No Quartus fit, timing claim, sweep, sibling deployment or SD update.',limits=['Native simulation uses fixed synthetic display/audio arrivals and bounded guest services; no sustained Pocket FPS claim.','Same-ELF controls isolate hardware/capability effects. The prior qualified app uses a different ELF and is an additional adoption baseline.','Function-profile gaps are diagnostic attribution; no instruction-count or estimated-latency subtraction is counted as performance.'],evidence_sha256=evidence)
out=A/'analysis/conclusion-v1.json';assert not out.exists();out.write_text(json.dumps(result,indent=2)+'\n')
lines=['AJ01 asynchronous geometry experiment — measured decision','',result['decision'],'','Revision          Control cycles (cold / warm)     AJ01 cycles (cold / warm)       Total change']
for r in revisions:lines.append(f"{r['label']:17} {r['control_cycles'][0]:,} / {r['control_cycles'][1]:,}       {r['candidate_cycles'][0]:,} / {r['candidate_cycles'][1]:,}       +{r['total_change_percent']:.2f}%")
lines+=['','Positive change means slower. The best trial remains 19.57% slower in total','than the previous qualified app/core (different ELF: 3,980,965 / 4,366,717).','','Implemented: immutable context/job packets in the existing ingress RAM;','autonomous transform/cull/packet generation through the existing arithmetic unit;','ordered CPU clipping repair; lazy legacy raw leases; cached dead-slot admission.','V2 reduces polling. V3 remembers exact immutable meshes that needed repair and','routes later occurrences through the original renderer without assuming clip results.','','Correctness: all three paired runs pass exact frame/depth/history, game state,','FCSR/register, resolved draw/state/order and independent source/ownership checks.','All 708 original vertex-load call identities and 652 transform contexts reconcile.','Focused actual RTL tests cover full ingress/output, repair, lease and reset;','repair arithmetic is checked on the real CPU for 1,184 tasks and 66,348 words.','','V3 warm evidence: 76 queued jobs, zero repairs, 5,105,025 cycles (+10.19% versus','its control). Legacy lease pending: 599,773 cycles, including 524,552 while GPU','fragment processing was active. Output full: 580,588 cycles; 539,898 overlap GPU','fragment processing. Raw transform active: 202,210 cycles. These counts overlap','and must not be added or treated as removable frame time.','','The CPU is still blocked by sharing raw storage with queued work whose output','must drain into the GPU. Cutting repeated repair does not remove that dependency.','The next structural hypothesis is priority legacy access at safe engine boundaries,','with full context restoration and a proven ingress-full release path. It is not','implemented here and no performance gain is assumed.','','No physical compile, timing sweep or deployment was performed. The existing','production sources and installed core remain unchanged. The experiment is isolated.','','These are two prepared full native intervals, with bounded services and synthetic','scan/audio traffic. They are not sustained device FPS or physical timing results.','Detailed source-bound evidence: analysis/conclusion-v1.json and paired strict receipts.']
report=A/'REPORT.txt';assert not report.exists();report.write_text('\n'.join(lines)+'\n');print(report)
